/// One component of a view, told apart by type. A type an app does not know is skipped and the rest drawn.
nonisolated enum ExtensionComponent: Codable, Hashable, Sendable {
    case text(ExtensionTextComponent)
    case metric(ExtensionMetricComponent)
    case progress(ExtensionProgressComponent)
    case row(ExtensionRowComponent)
    case button(ExtensionButtonComponent)
    case link(ExtensionLinkComponent)
    case field(ExtensionFieldComponent)
    case divider(ExtensionDividerComponent)
    case chart(ExtensionChartComponent)
    case statGrid(ExtensionStatGridComponent)
    case segmented(ExtensionSegmentedComponent)
    case markdown(ExtensionMarkdownComponent)
    case table(ExtensionTableComponent)
    case empty(ExtensionEmptyComponent)
    case loading(ExtensionLoadingComponent)
    case html(ExtensionHtmlComponent)
    case header(ExtensionHeaderComponent)
    case breadcrumb(ExtensionBreadcrumbComponent)
    case fileTree(ExtensionFileTreeComponent)
    case code(ExtensionCodeComponent)
    case diff(ExtensionDiffComponent)
    case commentThread(ExtensionCommentThreadComponent)
    case composer(ExtensionComposerComponent)
    case image(ExtensionImageComponent)
    case grid(ExtensionGridComponent)
    case carousel(ExtensionCarouselComponent)
    /// A type this app does not know, or a variant it could not read: skipped when drawn.
    case unknown(type: String)

    static let types = ["text", "metric", "progress", "row", "button", "link", "field", "divider", "chart", "stat_grid", "segmented", "markdown", "table", "empty", "loading", "html", "header", "breadcrumb", "file_tree", "code", "diff", "comment_thread", "composer", "image", "grid", "carousel"]

    /// The UI version that brought each type.
    static let since: [String: Int] = ["text": 1, "metric": 1, "progress": 1, "row": 1, "button": 1, "link": 1, "field": 1, "divider": 1, "chart": 2, "stat_grid": 2, "segmented": 2, "markdown": 3, "table": 3, "empty": 3, "loading": 3, "html": 4, "header": 4, "breadcrumb": 4, "file_tree": 4, "code": 4, "diff": 4, "comment_thread": 4, "composer": 4, "image": 6, "grid": 6, "carousel": 6]

    private enum TagKey: String, CodingKey {
        case tag = "type"
    }

    var type: String {
        switch self {
        case .text: "text"
        case .metric: "metric"
        case .progress: "progress"
        case .row: "row"
        case .button: "button"
        case .link: "link"
        case .field: "field"
        case .divider: "divider"
        case .chart: "chart"
        case .statGrid: "stat_grid"
        case .segmented: "segmented"
        case .markdown: "markdown"
        case .table: "table"
        case .empty: "empty"
        case .loading: "loading"
        case .html: "html"
        case .header: "header"
        case .breadcrumb: "breadcrumb"
        case .fileTree: "file_tree"
        case .code: "code"
        case .diff: "diff"
        case .commentThread: "comment_thread"
        case .composer: "composer"
        case .image: "image"
        case .grid: "grid"
        case .carousel: "carousel"
        case .unknown(let t): t
        }
    }

    init(from decoder: Decoder) throws {
        let t = (try? decoder.container(keyedBy: TagKey.self).decode(String.self, forKey: .tag)) ?? ""
        switch t {
        case "text": self = (try? ExtensionTextComponent(from: decoder)).map { .text($0) } ?? .unknown(type: t)
        case "metric": self = (try? ExtensionMetricComponent(from: decoder)).map { .metric($0) } ?? .unknown(type: t)
        case "progress": self = (try? ExtensionProgressComponent(from: decoder)).map { .progress($0) } ?? .unknown(type: t)
        case "row": self = (try? ExtensionRowComponent(from: decoder)).map { .row($0) } ?? .unknown(type: t)
        case "button": self = (try? ExtensionButtonComponent(from: decoder)).map { .button($0) } ?? .unknown(type: t)
        case "link": self = (try? ExtensionLinkComponent(from: decoder)).map { .link($0) } ?? .unknown(type: t)
        case "field": self = (try? ExtensionFieldComponent(from: decoder)).map { .field($0) } ?? .unknown(type: t)
        case "divider": self = (try? ExtensionDividerComponent(from: decoder)).map { .divider($0) } ?? .unknown(type: t)
        case "chart": self = (try? ExtensionChartComponent(from: decoder)).map { .chart($0) } ?? .unknown(type: t)
        case "stat_grid": self = (try? ExtensionStatGridComponent(from: decoder)).map { .statGrid($0) } ?? .unknown(type: t)
        case "segmented": self = (try? ExtensionSegmentedComponent(from: decoder)).map { .segmented($0) } ?? .unknown(type: t)
        case "markdown": self = (try? ExtensionMarkdownComponent(from: decoder)).map { .markdown($0) } ?? .unknown(type: t)
        case "table": self = (try? ExtensionTableComponent(from: decoder)).map { .table($0) } ?? .unknown(type: t)
        case "empty": self = (try? ExtensionEmptyComponent(from: decoder)).map { .empty($0) } ?? .unknown(type: t)
        case "loading": self = (try? ExtensionLoadingComponent(from: decoder)).map { .loading($0) } ?? .unknown(type: t)
        case "html": self = (try? ExtensionHtmlComponent(from: decoder)).map { .html($0) } ?? .unknown(type: t)
        case "header": self = (try? ExtensionHeaderComponent(from: decoder)).map { .header($0) } ?? .unknown(type: t)
        case "breadcrumb": self = (try? ExtensionBreadcrumbComponent(from: decoder)).map { .breadcrumb($0) } ?? .unknown(type: t)
        case "file_tree": self = (try? ExtensionFileTreeComponent(from: decoder)).map { .fileTree($0) } ?? .unknown(type: t)
        case "code": self = (try? ExtensionCodeComponent(from: decoder)).map { .code($0) } ?? .unknown(type: t)
        case "diff": self = (try? ExtensionDiffComponent(from: decoder)).map { .diff($0) } ?? .unknown(type: t)
        case "comment_thread": self = (try? ExtensionCommentThreadComponent(from: decoder)).map { .commentThread($0) } ?? .unknown(type: t)
        case "composer": self = (try? ExtensionComposerComponent(from: decoder)).map { .composer($0) } ?? .unknown(type: t)
        case "image": self = (try? ExtensionImageComponent(from: decoder)).map { .image($0) } ?? .unknown(type: t)
        case "grid": self = (try? ExtensionGridComponent(from: decoder)).map { .grid($0) } ?? .unknown(type: t)
        case "carousel": self = (try? ExtensionCarouselComponent(from: decoder)).map { .carousel($0) } ?? .unknown(type: t)
        default: self = .unknown(type: t)
        }
    }

    func encode(to encoder: Encoder) throws {
        switch self {
        case .text(let v): try v.encode(to: encoder)
        case .metric(let v): try v.encode(to: encoder)
        case .progress(let v): try v.encode(to: encoder)
        case .row(let v): try v.encode(to: encoder)
        case .button(let v): try v.encode(to: encoder)
        case .link(let v): try v.encode(to: encoder)
        case .field(let v): try v.encode(to: encoder)
        case .divider(let v): try v.encode(to: encoder)
        case .chart(let v): try v.encode(to: encoder)
        case .statGrid(let v): try v.encode(to: encoder)
        case .segmented(let v): try v.encode(to: encoder)
        case .markdown(let v): try v.encode(to: encoder)
        case .table(let v): try v.encode(to: encoder)
        case .empty(let v): try v.encode(to: encoder)
        case .loading(let v): try v.encode(to: encoder)
        case .html(let v): try v.encode(to: encoder)
        case .header(let v): try v.encode(to: encoder)
        case .breadcrumb(let v): try v.encode(to: encoder)
        case .fileTree(let v): try v.encode(to: encoder)
        case .code(let v): try v.encode(to: encoder)
        case .diff(let v): try v.encode(to: encoder)
        case .commentThread(let v): try v.encode(to: encoder)
        case .composer(let v): try v.encode(to: encoder)
        case .image(let v): try v.encode(to: encoder)
        case .grid(let v): try v.encode(to: encoder)
        case .carousel(let v): try v.encode(to: encoder)
        case .unknown: break
        }
        var c = encoder.container(keyedBy: TagKey.self)
        try c.encode(type, forKey: .tag)
    }
}

